function ScoreFigures({sv}){return <div className="score-main"><div className="score-figure primary"><span className="score-caption">SEVERITY SCORE</span><div className="score-value"><b>{sv.score.toFixed(1)}</b><small>/ 100</small></div><span className="score-note">{sv.label?`${sv.label} band · `:''}higher = more impaired</span></div>{sv.predictedAq!=null&&<div className="score-figure"><span className="score-caption">PREDICTED AQ</span><div className="score-value"><b>{sv.predictedAq.toFixed(1)}</b><small>/ 100</small></div><div className="confidence-track"><i style={{width:`${Math.max(0,Math.min(100,sv.predictedAq))}%`}}/></div><span className="score-note">100 − severity score</span></div>}</div>}
function ScoreDetails({sv}){const u=sv.uncertainty,e=sv.evaluation;const evaluation=e?[e.method,e.participants!=null&&`${e.participants} participants`,e.mae!=null&&`mean error ${e.mae} points`,e.mean_baseline_mae!=null&&`${e.mean_baseline_mae} when guessing the average`].filter(Boolean).join(' · '):'Not reported for this model.';const limitation=e?.validated_on_whisper_transcripts===false?'Evaluated on human transcripts. That does not establish equivalent performance on automatic (Whisper) transcripts such as this one.':'This recording is not part of the data the model was evaluated on.';const basis=u?(u.coverage?` It is a validation-residual interval at ${Math.round(u.coverage*100)}% coverage.`:u.method?` Basis: ${u.method.split(';')[0]}.`:''):'';const interpretation=u?`${u.calibrated_probability?'':'The interval is not a calibrated probability.'}${basis}`:'No interval is available, so the score has no stated uncertainty.';const rows=[['Estimated score interval',u?`${u.interval[0]} – ${u.interval[1]}`:'Not available for this model'],['Evaluation',evaluation],['Limitations',limitation],['Interpretation',interpretation]];return <dl className="score-rows">{rows.map(([k,v])=><div key={k}><dt>{k}</dt><dd>{v}</dd></div>)}</dl>}
